import XCTest

@testable import CodeConnectKit

/// A run's title (minor 63), against the daemon's own bytes: `minor-46-wire.json` is what ccd emits for a run on a
/// stand-in host started with "fix the tests" (`fixtures/claude/`, regenerated by ccd's tests, copied here).
final class RunTitleTests: XCTestCase {
    private func summary(title present: Bool) throws -> SessionSummary {
        let url = try XCTUnwrap(Bundle(for: type(of: self)).url(forResource: "minor-46-wire", withExtension: "json"))
        let wire = try XCTUnwrap(try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url)).objectValue)
        var frame = try XCTUnwrap(wire["session_hosted_live"]?.objectValue)
        if !present { frame["title"] = nil }
        return try JSONDecoder().decode(SessionSummary.self, from: Data(JSONValue.object(frame).canonicalJSONString.utf8))
    }

    private func row(_ summary: SessionSummary) -> FleetRow {
        FleetRow(
            summary: summary, status: .running, subtitle: "", activity: nil,
            label: RunLabel(project: "tmp", qualifier: nil), capability: .control, blockedCount: 0,
            lastActivityAt: nil, cachedAt: nil, machineID: "m1", machineName: "m1 name")
    }

    /// A run is called by its title, the person's first words to it; one the daemon sends none for (an older daemon,
    /// or a run started at its computer), by its label.
    func testARunIsCalledByItsTitleElseItsLabel() throws {
        let titled = try summary(title: true)
        XCTAssertEqual(titled.title, "fix the tests")
        XCTAssertEqual(row(titled).title, "fix the tests")
        let untitled = try summary(title: false)
        XCTAssertNil(untitled.title)
        XCTAssertEqual(row(untitled).title, "tmp")
    }
}
